const src = $('Déposer une facture').first();
const fichier = Object.values(src.binary ?? {})[0];
if (!fichier) throw new Error('Aucun fichier reçu : déposez une facture au format PDF.');
return [{ json: { nom_fichier: fichier.fileName }, binary: { data: fichier } }];

