// Contrôles de cohérence, détection de doublon et écriture comptable (plan comptable général).
const ia = $('Lecture IA de la facture').first().json.output;
const fichier = $('Préparer le fichier').first().json.nom_fichier;
const num = s => Math.round(Number(String(s ?? 0).replace(',', '.')) * 100) / 100;
const ht = num(ia.montant_ht), tva = num(ia.montant_tva), ttc = num(ia.montant_ttc);
const siret = String(ia.siret ?? '').replace(/\D/g, '');
const norm = s => String(s ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');

const luhn = s => { let sum = 0; for (let i = 0; i < s.length; i++) { let n = +s[s.length - 1 - i]; if (i % 2) { n *= 2; if (n > 9) n -= 9; } sum += n; } return sum % 10 === 0; };
const sommeLignes = Math.round((ia.lignes ?? []).reduce((s, l) => s + num(l.total_ht || (num(l.quantite) * num(l.prix_unitaire_ht))), 0) * 100) / 100;
const deja = $input.all().map(i => i.json).filter(r => r && r.numero && norm(r.numero) === norm(ia.numero_facture) && norm(r.fournisseur) === norm(ia.fournisseur));

const controles = [
  { label: 'HT + TVA = TTC', ok: Math.abs(ht + tva - ttc) <= 0.02, detail: `${ht.toFixed(2)} + ${tva.toFixed(2)} = ${(ht + tva).toFixed(2)} € (facture : ${ttc.toFixed(2)} €)` },
  { label: 'Somme des lignes = total HT', ok: !(ia.lignes ?? []).length || Math.abs(sommeLignes - ht) <= 0.02, detail: `lignes : ${sommeLignes.toFixed(2)} € · total HT : ${ht.toFixed(2)} €` },
  { label: 'SIRET valide', ok: /^\d{14}$/.test(siret) && luhn(siret), detail: siret || 'absent' },
  { label: 'Date de facture lisible', ok: !isNaN(Date.parse(ia.date_facture)), detail: ia.date_facture || 'absente' },
  { label: 'Échéance postérieure à la facture', ok: !ia.date_echeance || Date.parse(ia.date_echeance) >= Date.parse(ia.date_facture), detail: ia.date_echeance || 'non précisée' },
  { label: 'Pas de doublon', ok: deja.length === 0, detail: deja.length ? 'déjà enregistrée' : 'nouvelle facture' },
];
const anomalies = controles.filter(c => !c.ok).map(c => c.label);
const doublon = deja.length > 0;

const comptes = {
  matieres_premieres: ['601000', 'Achats de matières premières'], marchandises: ['607000', 'Achats de marchandises'],
  fournitures: ['606300', "Fournitures d'entretien et petit équipement"], sous_traitance: ['611000', 'Sous-traitance générale'],
  energie: ['606100', 'Fournitures non stockables (eau, énergie)'], honoraires: ['622600', 'Honoraires'],
  transport: ['624100', 'Transports sur achats'], autre: ['628000', 'Divers'],
};
const [compte, libCompte] = comptes[ia.categorie] ?? comptes.autre;
const compteFournisseur = '401' + norm(ia.fournisseur).toUpperCase().slice(0, 5);
const libelle = `${ia.fournisseur} · ${ia.numero_facture}`;
const ecriture = [
  { compte, libelle: libCompte, debit: ht, credit: 0 },
  { compte: '445660', libelle: 'TVA déductible sur biens et services', debit: tva, credit: 0 },
  { compte: compteFournisseur, libelle: 'Fournisseur ' + ia.fournisseur, debit: 0, credit: ttc },
];
const statut = doublon ? 'doublon' : anomalies.length ? 'a_verifier' : 'prete';
return [{ json: {
  fournisseur: ia.fournisseur, siret, tva_intracom: ia.tva_intracom ?? '', numero: ia.numero_facture,
  date_facture: ia.date_facture, echeance: ia.date_echeance || null, montant_ht: ht, montant_tva: tva, montant_ttc: ttc,
  categorie: ia.categorie, compte, statut, anomalies: anomalies.join(' · '), fichier,
  doublon, controles, ecriture, libelle, lignes: ia.lignes ?? [],
} }];
